css:
.lm-html{--ink: #1d1b16; --muted: #625b4e; --paper: #fbf7ef; --card: #ffffff; --line: #e4dccb; --brand: #0f6b5c; --brand-dark: #0a5045; --sun: #f2b544;}
*{box-sizing: border-box;}
.lm-html, .lm-body{margin: 0px;}
.lm-body{font-family: "lmw-fieldnote-Space-Grotesk", system-ui, sans-serif; color: var(--ink); background: var(--paper); font-size: 17px; line-height: 1.5;}
a{color: inherit; text-decoration: none;}
.wrap{width: 1120px; margin: 0px auto;}
header.top{border-bottom: 1px solid var(--line); background: var(--paper);}
header.top .wrap{display: flex; align-items: center; height: 76px; gap: 36px;}
.logo{display: flex; align-items: center; gap: 10px; font-family: "lmw-fieldnote-Fraunces", serif; font-weight: 600; font-size: 24px;}
.logo img{width: 34px; height: 34px;}
nav.main{display: flex; gap: 28px; flex: 1 1 0%;}
nav.main a{color: var(--muted); padding: 6px 2px; border-bottom: 2px solid transparent;}
nav.main a.lm-hover{color: var(--ink); border-bottom-color: var(--sun);}
.signin{color: var(--muted);}
.signin.lm-hover{color: var(--ink);}
.btn{display: inline-block; border: 0px; border-radius: 999px; padding: 12px 22px; font: 600 16px "lmw-fieldnote-Space-Grotesk", sans-serif; cursor: pointer;}
.btn.primary{background: var(--brand); color: rgb(255, 255, 255); box-shadow: 0 2px 0 var(--brand-dark);}
.btn.primary.lm-hover{background: var(--brand-dark);}
.btn.primary.lm-active{transform: translateY(2px); box-shadow: none;}
.btn.ghost{background: transparent; color: var(--ink); border: 1.5px solid var(--line);}
.btn.ghost.lm-hover{border-color: var(--ink);}
.hero .wrap{display: grid; grid-template-columns: 1.15fr 1fr; gap: 56px; padding: 64px 0px 56px; align-items: center;}
.kicker{text-transform: uppercase; letter-spacing: 0.14em; font-size: 13px; font-weight: 600; color: var(--brand);}
h1{font-family: "lmw-fieldnote-Fraunces", serif; font-weight: 600; font-size: 54px; line-height: 1.06; margin: 14px 0px 18px;}
.lead{font-size: 19px; color: var(--muted); max-width: 520px;}
.signup{background: var(--card); border: 1px solid var(--line); border-radius: 18px; padding: 28px; box-shadow: rgba(40, 30, 10, 0.35) 0px 18px 40px -24px;}
.signup h2{margin: 0px 0px 4px; font-size: 22px;}
.signup p{margin: 0px 0px 18px; color: var(--muted); font-size: 15px;}
.field{margin-bottom: 14px;}
.field label{display: block; font-size: 14px; font-weight: 600; margin-bottom: 6px;}
.field input, .field select{width: 100%; font: 400 16px "lmw-fieldnote-Space-Grotesk", sans-serif; color: var(--ink); background: var(--paper); border: 1.5px solid var(--line); border-radius: 10px; padding: 11px 14px; outline: none;}
.field input.lm-focus, .field select.lm-focus{border-color: var(--brand); background: rgb(255, 255, 255); box-shadow: rgba(15, 107, 92, 0.16) 0px 0px 0px 4px;}
.check{display: flex; gap: 10px; align-items: center; font-size: 14px; color: var(--muted); margin: 6px 0px 18px;}
.check input{width: 18px; height: 18px; accent-color: var(--brand);}
.signup .btn{width: 100%;}
.features{padding: 40px 0px 24px;}
.features h2, .pricing h2, .faq h2{font-family: "lmw-fieldnote-Fraunces", serif; font-weight: 600; font-size: 34px; margin: 0px 0px 22px;}
.cards{display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px;}
.card{background: var(--card); border: 1px solid var(--line); border-radius: 16px; padding: 24px;}
.card.lm-hover{border-color: var(--brand); box-shadow: rgba(15, 107, 92, 0.6) 0px 14px 30px -20px;}
.card .ico{width: 42px; height: 42px; border-radius: 12px; background: rgb(231, 242, 238); display: grid; place-items: center; margin-bottom: 14px;}
.card h3{margin: 0px 0px 6px; font-size: 19px;}
.card p{margin: 0px; color: var(--muted); font-size: 15px;}
.pricing{padding: 48px 0px;}
.switch{display: inline-flex; background: rgb(239, 231, 214); border-radius: 999px; padding: 4px; margin-bottom: 22px;}
.switch span{padding: 8px 16px; border-radius: 999px; font-size: 14px; font-weight: 600; color: var(--muted);}
.switch .m{background: rgb(255, 255, 255); color: var(--ink);}
.plans.yearly .switch .m{background: transparent; color: var(--muted);}
.plans.yearly .switch .y{background: rgb(255, 255, 255); color: var(--ink);}
.plans .price .yr{display: none;}
.plans.yearly .price .mo{display: none;}
.plans.yearly .price .yr{display: inline;}
.tiers{display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px;}
.tier{background: var(--card); border: 1px solid var(--line); border-radius: 16px; padding: 26px;}
.tier.best{border: 2px solid var(--brand);}
.tier h3{margin: 0px; font-size: 18px;}
.price{font-family: "lmw-fieldnote-Fraunces", serif; font-size: 40px; margin: 8px 0px 4px;}
.price small{font-family: "lmw-fieldnote-Space-Grotesk", sans-serif; font-size: 15px; color: var(--muted);}
.tier ul{padding-left: 18px; color: var(--muted); font-size: 15px;}
.faq{padding: 24px 0px 64px;}
.faq details{border-top: 1px solid var(--line); padding: 16px 0px;}
.faq summary{font-weight: 600; font-size: 18px; list-style: none;}
.faq details p{color: var(--muted); margin: 10px 0px 0px;}
footer{border-top: 1px solid var(--line); color: var(--muted); font-size: 14px;}
footer .wrap{padding: 28px 0px; display: flex; justify-content: space-between;}
